const commits = $input.item.json.commits || [];
const codeFiles = [];
commits.forEach(commit => {
  const files = [...(commit.added || []), ...(commit.modified || [])];
  files.forEach(f => {
    if (f.match(/\.(js|ts|py|go|java|php|rb)$/) && !f.includes('test') && !f.includes('spec')) {
      codeFiles.push(f);
    }
  });
});
const unique = [...new Set(codeFiles)].slice(0, 5);
return [{ json: { files: unique, repo: $input.item.json.repository.full_name, branch: $input.item.json.ref.replace('refs/heads/','') } }];

const encoded = $input.item.json.content;
const decoded = Buffer.from(encoded.replace(/\n/g,''), 'base64').toString('utf-8');
const truncated = decoded.length > 6000 ? decoded.substring(0,6000) + '...' : decoded;
return [{ json: { code: truncated, filename: $input.item.json.name, path: $input.item.json.path, repo: $('Filter Code Changes').item.json.repo } }];

const raw = $input.item.json.text.replace(/```json|```/g,'').trim();
const docs = JSON.parse(raw);
return [{ json: { ...docs, file_info: $('Decode File Content').item.json } }];

